class Solution:
    def countGreatEnoughNodes(self, root, k: int) -> int:
        ans = 0
        def dfs(node):
            nonlocal ans
            if not node:
                return []
            left_vals = dfs(node.left)
            right_vals = dfs(node.right)
            merged = sorted(left_vals + right_vals)[:k]
            if len(merged) == k and merged[-1] < node.val:
                ans += 1
            return sorted(merged + [node.val])[:k]
        dfs(root)
        return ans

class Solution {
public:
    int countGreatEnoughNodes(TreeNode* root, int k) {
        int ans = 0;
        dfs(root, k, ans);
        return ans;
    }

private:
    vector<int> dfs(TreeNode* root, int k, int& ans) {
        if (!root) return {};
        auto left_vals = dfs(root->left, k, ans);
        auto right_vals = dfs(root->right, k, ans);
        vector<int> merged;
        merged.reserve(left_vals.size() + right_vals.size());
        merged.insert(merged.end(), left_vals.begin(), left_vals.end());
        merged.insert(merged.end(), right_vals.begin(), right_vals.end());
        sort(merged.begin(), merged.end());
        if (merged.size() > k) merged.resize(k);
        if (merged.size() == k && merged.back() < root->val) {
            ans++;
        }
        merged.push_back(root->val);
        sort(merged.begin(), merged.end());
        if (merged.size() > k) merged.resize(k);
        return merged;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    private int ans = 0;

    public int countGreatEnoughNodes(TreeNode root, int k) {
        ans = 0;
        dfs(root, k);
        return ans;
    }

    private List<Integer> dfs(TreeNode root, int k) {
        if (root == null) return new ArrayList<>();
        List<Integer> left = dfs(root.left, k);
        List<Integer> right = dfs(root.right, k);
        List<Integer> merged = new ArrayList<>(left.size() + right.size());
        merged.addAll(left);
        merged.addAll(right);
        Collections.sort(merged);
        while (merged.size() > k) merged.remove(merged.size() - 1);
        if (merged.size() == k && merged.get(k - 1) < root.val) {
            ans++;
        }
        merged.add(root.val);
        Collections.sort(merged);
        while (merged.size() > k) merged.remove(merged.size() - 1);
        return merged;
    }
}

